// Nombre corto y estado, porque el export arrastra "(Deactivated User)".
window.aeNombre = function (k) {
  return k.replace(/\s*\(Deactivated User\)\s*/, '').trim();
};
window.aeActivo = function (k) { return !/Deactivated/.test(k); };

