// TAE por segmento, de la hoja Objetivos_Outbound (columna O). Hoy es 25% en
// los cuatro segmentos, así que la media ponderada sale plana: el ranking por
// TAE no discrimina hasta que el CRM traiga la TAE de cada operación.
window.AE_TAE_SEG = { midmkt:0.25, big:0.25, mid:0.25, small:0.25, corp:0.25 };
// Precio por deal, que se mantiene como segunda lectura.
window.AE_PRECIO_SEG = { midmkt:150, big:100, mid:50, small:25, corp:150 };
window.AE_TAE_PLANA = (() => {
  const v = Object.values(window.AE_TAE_SEG);
  return v.every(x => x === v[0]);
})();

// Pricing cerrado imputado: mezcla de segmentos × precio del segmento. No hay
// tarifa por deal en el export, así que esto es una imputación declarada.
// Media ponderada de una tabla por segmento sobre los deals GANADOS: un precio
// o una TAE "cerrada" no pueden salir de deals abiertos.
window.aePonderado = function (a, tabla) {
  const segs = a.wsegs || {};
  let n = 0, acc = 0;
  Object.keys(segs).forEach(k => {
    const p = tabla[k];
    if (p == null) return;
    n += segs[k]; acc += segs[k] * p;
  });
  return n ? acc / n : null;
};
window.aePricing = function (a) { return window.aePonderado(a, window.AE_PRECIO_SEG); };
window.aeTae = function (a) { return window.aePonderado(a, window.AE_TAE_SEG); };
// Deals ganados con segmento, que es el denominador con el que hay que ponderar
// el pricing del equipo para no dar peso a quien no cierra.
window.aePricingBase = function (a) {
  return Object.keys(a.wsegs || {}).reduce((x, k) => x + (window.AE_PRECIO_SEG[k] != null ? a.wsegs[k] : 0), 0);
};

