window.aeMonths = function (desde) {
  const out = [];
  let y = +(desde || '2025-01').slice(0,4), m = +(desde || '2025-01').slice(5,7);
  const L = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  while (true) {
    const id = y + '-' + String(m).padStart(2,'0');
    out.push({ id, y, m, label: L[m-1] + ' ' + String(y).slice(2), q:'Q' + Math.ceil(m/3) });
    if (id === window.AE_META.corte) break;
    m++; if (m > 12) { m = 1; y++; }
  }
  return out;
};

// Cierra la ficha de cada AE con todo lo derivado, para que el componente no
// tenga que calcular nada dos veces.
window.aePerf = function (opts) {
  const o = opts || {};
  const months = window.aeMonths(o.desde);
  const list = Object.keys(window.AE_DATA).map(k => {
    const a = window.AE_DATA[k];
    const cerrados = a.w + a.l;
    const rows = months.map(mo => {
      const x = a.meses[mo.id];
      return { ...mo, d: x ? x.d : 0, w: x ? x.w : 0, l: x ? x.l : 0, eur: x ? x.eur : 0,
        wr: x && (x.w + x.l) ? x.w / (x.w + x.l) : null };
    });
    // Racha de meses consecutivos con cliente.
    let racha = 0, mejor = 0;
    rows.forEach(r => { if (r.w > 0) { racha++; mejor = Math.max(mejor, racha); } else racha = 0; });
    const mesesTot = Object.keys(a.meses).length;
    const activos = rows.filter(r => r.d > 0).length;
    return { key:k, nombre: window.aeNombre(k), activo: window.aeActivo(k),
      ...a, rows, cerrados,
      wr: cerrados ? a.w / cerrados : null,
      ticket: a.w ? a.eurW / a.w : null,
      // Precio implícito: lo que cuesta cada cliente en deals trabajados.
      dealsPorCliente: a.w ? a.d / a.w : null,
      ritmo: activos ? rows.reduce((x,r)=>x+r.d,0) / activos : null,
      ritmoCli: activos ? rows.reduce((x,r)=>x+r.w,0) / activos : null,
      mesesConCliente: rows.filter(r => r.w > 0).length,
      mesesActivo: (() => {
        const f = a.first.split('-').map(Number), l = a.last.split('-').map(Number);
        return (l[0]-f[0])*12 + (l[1]-f[1]) + 1;
      })(),
      mejorMes: Math.max(0, ...rows.map(r => r.w)),
      mejorEur: Math.max(0, ...rows.map(r => r.eur)),
      racha: mejor,
      semanal: activos ? rows.reduce((x,r)=>x+r.d,0) / activos / 4.33 : null,
    };
  });
  list.forEach(a => {
    a.pricing = window.aePricing(a);
    a.tae = window.aeTae(a);
    a.pricingBase = window.aePricingBase(a);
    a.badges = window.AE_BADGES.filter(b => b.test(a)).map(b => b.id);
  });
  const totalRows = months.map((mo, i) => ({ ...mo,
    d: list.reduce((x,a)=>x+a.rows[i].d,0),
    w: list.reduce((x,a)=>x+a.rows[i].w,0),
    l: list.reduce((x,a)=>x+a.rows[i].l,0),
    eur: list.reduce((x,a)=>x+a.rows[i].eur,0) }));
  totalRows.forEach(r => { r.wr = (r.w + r.l) ? r.w / (r.w + r.l) : null; });
  return { months, list, totalRows,
    activos: list.filter(a => a.activo),
    tot: { d: list.reduce((x,a)=>x+a.d,0), w: list.reduce((x,a)=>x+a.w,0),
      eurW: list.reduce((x,a)=>x+a.eurW,0),
      wr: (() => { const c = list.reduce((x,a)=>x+a.cerrados,0); return c ? list.reduce((x,a)=>x+a.w,0)/c : null; })() } };
};
